def bf(planet1, planet2):
    planets = {
        "mercury": 1,
        "venus": 2,
        "earth": 3,
        "mars": 4,
        "jupiter": 5,
        "saturn": 6,
        "uranus": 7,
        "neptune": 8
    }

    if planet1.lower() not in planets or planet2.lower() not in planets:
        return ()

    start = min(planets[planet1.lower()], planets[planet2.lower()])
    end = max(planets[planet1.lower()], planets[planet2.lower()])

    result = [planet for planet, distance in planets.items() if start < distance < end]
    result.sort(key=lambda x: planets[x])

    return tuple(result)
